Considering the following definition of the function, named “bitwise”, what will be returned when we call bitwise(2147483649)?
unsigned int bitwise(unsigned int x)
{
    int n = sizeof(x) * 8;
    int i, j;
    unsigned int mask1 = 1;
    unsigned int mask2 = 1<<31;

    while (mask1 < mask2)
    {
        int i = ((x & mask1) != 0);
        int j = ((x & mask2) != 0);

        if (i^j != 0)
        {
            x = ((x ^ mask1) ^ mask2);
        }

        mask1 <<= 1;
        mask2 >>= 1;
    }

    return x;
}
(a) 0
(b) 2147483647
(c) 4294967295
(d) 2147483649

